-- READ ONLY, one MVCC statement. Minimal private reconciliation fields only.
-- No names, customer records, IP addresses, payloads, keys or payment links.
SELECT jsonb_build_object('format','newhope-operational-server-v1','capturedAt',statement_timestamp(),'sourceFrozen',false,
 'merchants',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'tenantId',tenant_id,'businessRef',external_ref,'active',is_active) ORDER BY id),'[]') FROM internal.merchants),
 'outlets',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'tenantId',tenant_id,'merchantId',merchant_id,'active',is_active) ORDER BY id),'[]') FROM internal.outlets),
 'deviceFingerprints',(SELECT jsonb_build_object('count',count(*),'latestSeen',max(created_at),'fleetInventoryComplete',false,'scope','Billing fingerprints are not an active POS fleet registry') FROM billing.device_fingerprints),
 'transactions',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'tenantId',tenant_id,'merchantId',merchant_id,'outletId',outlet_id,'clientTxnId',client_txn_id,'invoiceNumber',to_jsonb(t)->>'invoice_number','amount',total_amount::text,'paymentStatus',payment_status,'createdAt',created_at) ORDER BY id),'[]') FROM pos.transactions t),
 'payments',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'tenantId',tenant_id,'merchantId',merchant_id,'transactionId',transaction_id,'clientPaymentId',to_jsonb(t)->>'client_payment_id','amount',amount::text,'paymentStatus',payment_status,'providerReference',gateway_reference) ORDER BY id),'[]') FROM pos.payments t),
 'receipts',(SELECT coalesce(jsonb_agg(jsonb_build_object('idempotencyKey',idempotency_key,'tenantId',tenant_id,'businessRef',business_id,'accepted',rows_accepted,'duplicates',rows_duplicate,'receivedAt',received_at) ORDER BY idempotency_key),'[]') FROM pos.sync_receipts),
 'invoices',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'tenantId',tenant_id,'invoiceNumber',invoice_number,'checkoutKey',checkout_key,'amount',amount::text,'currency',currency,'paymentStatus',payment_status,'providerReference',payment_gateway_ref,'reconciliationStatus',reconciliation_status) ORDER BY id),'[]') FROM billing.invoices),
 'events',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'eventKey',event_key,'invoiceNumber',invoice_number,'providerReference',gateway_reference,'amount',amount::text,'currency',currency,'outcome',outcome,'createdAt',created_at) ORDER BY id),'[]') FROM billing.payment_events),
 'webhooks',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'eventKey',event_id,'processedAt',processed_at) ORDER BY id),'[]') FROM billing.webhook_logs),
 'posProviderEvents',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'tenantId',tenant_id,'eventKey',provider_event_ref,'providerReference',provider_payment_ref,'orderReference',order_reference,'amount',amount::text,'currency',currency,'outcome',outcome,'receivedAt',received_at) ORDER BY id),'[]') FROM pos.payment_reconciliation_events),
 'refunds',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'tenantId',tenant_id,'merchantId',merchant_id,'outletId',outlet_id,'clientEventId',to_jsonb(r)->>'client_event_id','clientRefundId',to_jsonb(r)->>'client_refund_id','amount',amount::text) ORDER BY id),'[]') FROM pos.transaction_refunds r),
 'cash',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'tenantId',tenant_id,'merchantId',merchant_id,'outletId',outlet_id,'eventType',event_type,'clientEventId',to_jsonb(c)->>'client_event_id','amount',amount::text) ORDER BY id),'[]') FROM pos.cash_ledger c),
 'externalProviderQueueVerified',false,'clientOfflineQueuesVerified',false,'cutoverAllowed',false) checkpoint;
